'use strict';
importScripts('/architecture-catalog.js','/m05-library.js','/m05-modules.js','/architecture-surfaces.js','/m05-facade-library.js','/m05-facade.js','/m05-roof-forms.js','/m05-roof.js','/m05-kit.js','/signature-design.js','/workshop-design.js','/workshop-model.js','/flow-core.js','/workshop-assist.js','/workshop-planning.js','/creation-living.js','/design-campus.js','/creation-fitting.js');
self.onmessage=async event=>{try{const project=await WorkshopPlanning.build(event.data,{progress:value=>postMessage({progress:value}),manifold:async body=>{const response=await fetch('/api/workshop/manifold',{method:'POST',headers:{'Content-Type':'application/json','X-Factory-Tools':'local-viewer'},body:JSON.stringify(body)}),data=await response.json();if(!response.ok)throw new Error(data.error||'Manifolds indisponibles.');return data.project;},compact:async body=>{const response=await fetch('/api/workshop/compact',{method:'POST',headers:{'Content-Type':'application/json','X-Factory-Tools':'local-viewer'},body:JSON.stringify(body)}),data=await response.json();if(!response.ok)throw new Error(data.error||'Modules compacts indisponibles.');return data.project;}});postMessage({project});}catch(error){postMessage({error:error.message});}};

